originalNoticeBody:
margin: 0;
padding: 10px 12px;
border: 1px solid var(--border);
border-radius: var(--radius-sm);
background: color-mix(in srgb, var(--bg-card) 76%, transparent);
color: var(--text-muted);
font-size: 11.5px;
line-height: 1.5;

loweredBlock:
:where(.gb\:feedback-notice\:feedback-notice-block):where(#feedback-modal, #feedback-modal *):is(.feedback-notice) {
  margin: 0;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-card);
  @supports (color: color-mix(in lab, red, red)) {
    background: color-mix(in srgb, var(--bg-card) 76%, transparent);
  }
  color: var(--text-muted);
  font-size: 11.5px;
  line-height: 1.5;
}
